#include <iostream>
#include <algorithm>

using namespace std;


const int N = 1010;


int dp[N][N];


int main()
{
    int n,m;


    string a,b;


    cin >> n >> m;

    cin >> a;

    cin >> b;



    // 下标从1开始方便处理
    a = " " + a;
    b = " " + b;



    for(int i=1;i<=n;i++)
    {
        for(int j=1;j<=m;j++)
        {
            if(a[i] == b[j])
            {
                dp[i][j] =
                    dp[i-1][j-1] + 1;
            }
            else
            {
                dp[i][j] =
                    max(
                        dp[i-1][j],
                        dp[i][j-1]
                    );
            }
        }
    }



    cout << dp[n][m];


    return 0;
}
